  updated: {"ar":"تم التحديث","en":"Updated","ur":"اپ ڈیٹ ہو گیا","bn":"আপডেট হয়েছে","hi":"अपडेट हुआ","ml":"അപ്ഡേറ്റ് ചെയ്തു","fil":"Na-update","id":"Diperbarui","ne":"अद्यतन","am":"የዘመነ","tr":"Güncelleştirilmiş"},
