  no_updates: {"ar":"لا تحديثات","en":"No updates","ur":"کوئی اپ ڈیٹ نہیں","bn":"কোনো আপডেট নেই","hi":"कोई अपडेट नहीं","ml":"അപ്ഡേറ്റുകളില്ല","fil":"Walang mga update","id":"Tidak ada update","ne":"कुनै अपडेट छैन","am":"ምንም ዝማኔዎች","tr":"Güncelleştirilmez"},
